from common import *
# NAMES is a literal fixed before closure, staging and commit.
pub=str((Q/'publication.json').relative_to(R));c=rd(Q/'closure.json')
require(c['all_passed'] is True and bindings(c),'Closure failed or changed')
require(not git('diff','--cached','--name-only'),'Index not empty')
actual=set(git('diff','--name-only').splitlines())|set(git('ls-files','--others','--exclude-standard').splitlines())
require(actual-{'Manifest.toml','LocalPreferences.toml'}==set(NAMES)-{pub},'Exact change membership failed')
others=[n for n in NAMES if n!=pub]
subprocess.run(['git','add','--',*others],cwd=R,check=True)
require(git('diff','--cached','--name-only').splitlines()==others,'Exact staged names failed')
blobs={n:git('rev-parse',':'+n) for n in others}
require(all(blobs[n]==git('hash-object',n) for n in others),'Staged byte mismatch')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
save(Q/'publication.json',dict(all_passed=True,scope='Reviewed optional managed native pivot policy source/design plan; production/master unchanged',exact_names=NAMES,staged_blobs_excluding_self=blobs,sha256={n:sha(R/n) for n in others}))
subprocess.run(['git','add','--',pub],cwd=R,check=True)
require(git('diff','--cached','--name-only').splitlines()==NAMES,'Final exact membership failed')
subprocess.run(['git','diff','--cached','--check'],cwd=R,check=True)
print(dict(all_passed=True,exact_names=len(NAMES),bound_blobs=len(blobs)))
